                _q(6, 12, 'application', 'Nếu tổ chức một buổi thuyết trình nhóm về tác phẩm "Mona Lisa" trước lớp, góc phân tích nghệ thuật nào giúp các bạn hiểu sâu hơn thay vì chỉ nói "tranh rất nổi tiếng"?',
                   'Phân tích kĩ thuật sfumato tạo khói mờ khóe miệng khóe mắt, bố cục tam giác vững vàng và chiều sâu núi non sương mờ phía sau',
                   ['Chỉ nói rằng bức tranh đắt tiền và treo ở nước ngoài từ lâu', 'Đo xem khung gỗ nặng bao nhiêu gam rồi kết thúc bài nói', 'Chế ảnh ghép vui nhộn làm méo mó gương mặt nhân vật'],
                   'Cung cấp công cụ giải mã ngôn ngữ hội họa giúp học sinh biết cách thưởng thức bảo tàng một cách chủ động và sâu sắc.',
                   'Kĩ năng phân tích thưởng thức kiệt tác'),
                _q(6, 13, 'advanced', 'Vì sao phát minh ra máy ảnh vào giữa thế kỉ XIX lại vô tình trở thành động lực lớn thúc đẩy trường phái Ấn tượng và sau đó là nghệ thuật Hiện đại từ bỏ lối vẽ giống hệt như ảnh chụp?',
                   'Máy ảnh sao chép thực tại nhanh hơn tay người, giải phóng hội họa khỏi việc chép tự nhiên để tìm kiếm cảm xúc, ánh sáng và nội tâm riêng',
                   ['Vì sau khi có máy ảnh, toàn bộ các họa sĩ đều bỏ nghề đi làm thợ sửa máy', 'Vì máy ảnh cấm không cho phép con người sử dụng bút vẽ sơn dầu nữa', 'Vì ảnh chụp thời kì đầu in ra hàng triệu màu sắc rực rỡ hơn mắt người'],
                   'Thay vì cạnh tranh vô ích với ống kính máy ảnh, hội họa đã bứt phá ngoạn mục sang thế giới của ánh sáng, màu sắc và trừu tượng.',
                   'Tác động của nhiếp ảnh tới hội họa hiện đại'),
